<?php
namespace EventFlow\Presentation\Api;
use DateTimeImmutable;use DateTimeZone;use EventFlow\Application\Error\RequestId;use EventFlow\Application\Idempotency\{IdempotencyOutcome};use EventFlow\Application\Import\{ImportApplyRequest,ImportJobPage,ImportJobRecord,ImportResult,ImportRowPage,ImportRowRecord};
final readonly class ImportAdministrationPresenter
{public function page(ImportJobPage$p,RequestId$r):JsonApiResponse{return new JsonApiResponse(200,['data'=>array_map($this->job(...),$p->jobs),'meta'=>['next_after'=>$p->nextAfterJobId],'request_id'=>$r->value],$this->headers($r));}public function resource(ImportJobRecord$j,RequestId$r):JsonApiResponse{return new JsonApiResponse(200,['data'=>$this->job($j),'request_id'=>$r->value],$this->headers($r,$j->revision));}public function rows(ImportRowPage$p,RequestId$r):JsonApiResponse{return new JsonApiResponse(200,['data'=>array_map($this->row(...),$p->rows),'meta'=>['next_after'=>$p->nextAfterRowId],'request_id'=>$r->value],$this->headers($r));}public function result(ImportResult$x,RequestId$r):JsonApiResponse{return new JsonApiResponse(200,['data'=>['import_job_id'=>$x->jobId,'status'=>$x->status->value,'total_rows'=>$x->totalRows,'ready_rows'=>$x->readyRows,'warning_rows'=>$x->warningRows,'invalid_rows'=>$x->invalidRows,'applied_rows'=>$x->appliedRows,'skipped_rows'=>$x->skippedRows,'failed_rows'=>$x->failedRows],'request_id'=>$r->value],$this->headers($r));}public function outcome(IdempotencyOutcome$o,int$eventId,RequestId$r):JsonApiResponse{$apply=$o->response instanceof ImportApplyRequest?$o->response:null;$job=$apply?->job??($o->response instanceof ImportJobRecord?$o->response:null);$data=$job===null?['type'=>$o->reference->entityType,'id'=>$o->reference->entityId]:$this->job($job);if($apply!==null)$data['worker_job_id']=$apply->workerJobId;$headers=$this->headers($r,$job?->revision);$headers['Location']='/wp-json/eventflow/v1/events/'.$eventId.'/imports/'.$o->reference->entityId;return new JsonApiResponse($o->reference->responseStatusCode,['data'=>$data,'meta'=>['replayed'=>$o->replayed],'request_id'=>$r->value],$headers);}public function creation(IdempotencyOutcome$o,int$eventId,RequestId$r):JsonApiResponse{$job=$o->response instanceof ImportJobRecord?$o->response:null;$data=$job===null?['type'=>$o->reference->entityType,'id'=>$o->reference->entityId]:$this->job($job);$headers=$this->headers($r,$job?->revision);$headers['Location']='/wp-json/eventflow/v1/events/'.$eventId.'/imports/'.$o->reference->entityId;return new JsonApiResponse($o->reference->responseStatusCode,['data'=>$data,'meta'=>['replayed'=>$o->replayed],'request_id'=>$r->value],$headers);}/** @return array<string,mixed> */private function job(ImportJobRecord$j):array{return['id'=>$j->jobId,'status'=>$j->status->value,'revision'=>$j->revision,'source_filename'=>$j->sourceFilename,'source_file_hash'=>$j->sourceFileHash,'mapping'=>$j->mapping,'total_rows'=>$j->totalRows,'valid_rows'=>$j->validRows,'warning_rows'=>$j->warningRows,'invalid_rows'=>$j->invalidRows,'applied_rows'=>$j->appliedRows,'skipped_rows'=>$j->skippedRows,'failed_rows'=>$j->failedRows,'uploaded_at'=>$this->date($j->uploadedAt),'validated_at'=>$this->date($j->validatedAt),'completed_at'=>$this->date($j->completedAt),'cancelled_at'=>$this->date($j->cancelledAt)];}/** @return array<string,mixed> */private function row(ImportRowRecord$x):array{return['id'=>$x->rowId,'import_job_id'=>$x->jobId,'source_row_number'=>$x->sourceRowNumber,'status'=>$x->status->value,'raw_data'=>$x->rawData,'normalized_data'=>$x->normalizedData,'errors'=>$x->errors,'warnings'=>$x->warnings];}/** @return array<string,string> */private function headers(RequestId$r,?int$v=null):array{$h=['X-Request-ID'=>$r->value,'Cache-Control'=>'no-store, max-age=0','Pragma'=>'no-cache'];if($v!==null)$h['ETag']='"'.$v.'"';return$h;}private function date(?DateTimeImmutable$d):?string{return$d?->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d\TH:i:s\Z');}}
